const app=document.querySelector('#app');
const answers={};let current=0;let nextTimer;let loadingTimer;
const config={checkoutUrl:'checkout.html',price:'R$ 10,00'};
const styles={'nao-sei':'Ainda não sei',rustico:'Rústico natural',floral:'Floral delicado',classico:'Clássico elegante',moderno:'Moderno minimalista',todos:'Todos os estilos'};
const pieces={americano:'jogos americanos',sousplat:'sousplats',trilho:'trilhos de mesa',sugestao:'jogos americanos'};
const goals={casa:'deixar sua casa mais bonita',vender:'ampliar suas opções para produzir e vender',presentear:'criar presentes com um toque pessoal',eventos:'montar mesas para eventos e festas'};
const levels={inicio:'Estou começando',alguma:'Já fiz algumas peças',pratica:'Já tenho prática'};
const pains={escolha:'Escolher o primeiro modelo',passo:'Entender o passo a passo',medo:'Ter segurança para começar',ideias:'Encontrar novos modelos'};
const advice={escolha:'Comece por uma única peça. Depois de escolher o modelo, confira as orientações e os materiais indicados antes de produzir.',passo:'Sua sequência sugerida é: conferir o molde, ler as orientações, separar os materiais e acompanhar a produção.',medo:'Faça uma peça de teste antes da composição completa. Isso ajuda a conferir medidas e entender a técnica com mais segurança.',tempo:'Organize uma pasta com seus moldes favoritos para não perder tempo procurando e imprimindo.','nao-sei':'Comece explorando as opções do seu estilo e escolha uma peça que desperte vontade de criar.',ideias:'Explore variações de cores e acabamentos a partir de um modelo que combine com a técnica que você já utiliza.'};
const questions={
 goal:{title:'Para que você quer<br><em>usar os moldes?</em>',sub:'Escolha uma opção.',options:[['casa','🏡','Decorar a minha casa',''],['vender','💰','Vender peças e kits',''],['eventos','🎉','Montar mesas para eventos e festas',''],['presentear','🎁','Hobby e presentes','']]},
 material:{title:'Com qual material<br><em>você trabalha?</em>',sub:'Escolha uma opção.',options:[['eva','🧩','EVA',''],['papel','📄','Papel e papel cartão',''],['tecido','🧵','Tecido e feltro',''],['corte','🖨️','Máquina de corte',''],['nao-sei','❔','Ainda não sei','']]},
 occasions:{title:'Para quais ocasiões<br><em>você monta mesa?</em>',sub:'Pode marcar mais de uma',multi:true,options:[['almoco','🍽️','Almoço de domingo',''],['aniversario','🎂','Aniversários',''],['natal','🎄','Natal e fim de ano',''],['casamento','💍','Casamento, chá e batizado','']]},
 pain:{title:'O que mais<br><em>atrapalha você hoje?</em>',sub:'Escolha uma opção.',options:[['escolha','📏','Moldes com tamanho errado ou sem medidas',''],['ideias','💡','Faltam ideias e variedade',''],['tempo','⌛','Perco tempo procurando e imprimindo',''],['medo','😟','Tenho medo de comprar e não gostar',''],['nao-sei','❔','Ainda não sei','']]},
 style:{title:'Qual estilo combina<br>com <em>a sua mesa?</em>',sub:'Escolha uma opção.',images:true,options:[['rustico','','Rústico natural',''],['floral','','Floral delicado',''],['classico','','Clássico elegante',''],['moderno','','Moderno minimalista',''],['todos','✨','Todas as opções','']]}
};
const steps=['intro','reviews','name','goal','material','occasions','pain','style','analyzing','preview','offer'];
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const stylePhotos={rustico:'estilo-rustico.png',floral:'estilo-floral.png',classico:'estilo-classico.png',moderno:'estilo-moderno.png'};
function person(){return escapeHtml(answers.name||'Você');}
function cta(label,id='continue'){return `<button class="btn" id="${id}">${label}<span aria-hidden="true">→</span></button>`}
function go(n){clearTimeout(nextTimer);clearInterval(loadingTimer);current=Math.max(0,Math.min(steps.length-1,n));render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('h1,h2')?.focus({preventScroll:true});}
function render(){const key=steps[current];document.querySelector('header').style.display=key==='offer'?'none':'block';document.querySelector('#back').disabled=current===0||['analyzing','finalizing'].includes(key);const percent=Math.round(current/(steps.length-1)*100);document.querySelector('#bar').style.width=`${percent}%`;document.querySelector('.progress').setAttribute('aria-valuenow',percent);if(questions[key])renderQuestion(key);else if(key==='intro')intro();else if(key==='reviews')reviews();else if(key==='name')nameStep();else if(key==='analyzing')loading();else if(key==='preview')preview();else offer();const heading=app.querySelector('h1,h2');if(heading)heading.setAttribute('tabindex','-1');}
function intro(){app.innerHTML=`<section class="step"><h1>Vamos encontrar os moldes<br>de mesa posta que mais<br><em>combinam com você?</em></h1><div class="intro-product"><img src="assets/abertura.jpeg" alt="Preparando uma mesa de Natal com guardanapos vermelhos, sousplats e velas"></div><p>Responda algumas perguntas para descobrir uma <strong>seleção indicada para seu estilo e seu momento.</strong></p>${cta('MONTAR MINHA SELEÇÃO')}<p class="tiny">⏱️ São 6 perguntas rápidas. Sem cadastro.</p></section>`;bindContinue();}
function reviews(){const photos=Array.from({length:6},(_,i)=>`<img src="assets/inspiracao-${i+1}.jpg" alt="Inspiração de mesa posta ${i+1}" draggable="false">`).join('');app.innerHTML=`<section class="step reviews-step"><div class="reviews-panel"><h1>Mais de <span class="accent">12.231 moldes personalizados</span> entregues</h1><div class="photo-carousel" aria-label="Galeria contínua de inspirações de mesa posta"><div class="photo-track"><div class="photo-set">${photos}</div><div class="photo-set" aria-hidden="true">${photos}</div></div></div><div class="review-card"><div class="review-person"><img class="review-avatar review-portrait" src="assets/avatar-review.png" alt="Foto fornecida para o exemplo de depoimento"><div><strong>Mariana · Apaixonada por mesa posta</strong><span class="review-stars" aria-label="Cinco estrelas ilustrativas">★★★★★</span></div></div><p>“Eu salvo um monte de ideias de mesa posta e depois fico sem saber por onde começar 😂 Queria muito uma seleção com a minha cara, pra escolher uma peça e finalmente colocar a mão na massa!”</p><small class="review-example">Depoimento demonstrativo · nome e texto fictícios</small></div>${cta('VAMOS COMEÇAR!')}<div class="review-badges"><span>♧ Compra segura</span><span>♢ Garantia de 7 dias</span><span>☆ 4,9 de 5</span></div><p class="rating-demo">Nota ilustrativa na prévia · substituir pela avaliação real.</p></div></section>`;bindContinue();}
function renderQuestion(key){const q=questions[key];const selected=answers[key]||[];const isMulti=!!q.multi;const chosen=v=>isMulti?selected.includes(v):selected===v;app.innerHTML=`<section class="step"><span class="label">CASA DO ARTESANATO</span><h1>${q.title}</h1><p>${q.sub}</p><div class="options ${q.images?'visual-options':''}" role="group" aria-label="${q.title.replace(/<[^>]*>/g,' ')}">${q.options.map(([value,emoji,title,desc])=>`<button class="choice ${value==='todos'?'all-styles':''} ${chosen(value)?'selected':''}" data-value="${value}" aria-pressed="${chosen(value)}">${q.images&&value==='todos'?`<div class="all-styles-collage" aria-hidden="true">${['rustico','floral','classico','moderno'].map(v=>`<img src="assets/${stylePhotos[v]}" alt="">`).join('')}</div>`:q.images&&stylePhotos[value]?`<img src="assets/${stylePhotos[value]}" alt="Mesa posta: ${title}">`:`<span class="emoji" aria-hidden="true">${emoji}</span>`}<span class="copy"><strong>${title}</strong>${desc?`<small>${desc}</small>`:''}</span><span class="circle" aria-hidden="true">${chosen(value)?'✓':''}</span></button>`).join('')}</div>${isMulti?`<button class="btn multi-continue" id="multi-continue" disabled>CONTINUAR <span>→</span></button>`:''}<p class="hint">${isMulti?'Marque uma ou mais opções e continue.':'Toque em uma opção para continuar.'}</p></section>`;app.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{const value=b.dataset.value;if(isMulti){let list=Array.isArray(answers[key])?answers[key]:[];list=list.includes(value)?list.filter(v=>v!==value):[...list,value];answers[key]=list;b.classList.toggle('selected',list.includes(value));b.setAttribute('aria-pressed',list.includes(value));b.querySelector('.circle').textContent=list.includes(value)?'✓':'';const goBtn=document.querySelector('#multi-continue');if(goBtn)goBtn.disabled=list.length===0;}else{answers[key]=value;if(key==='material')answers.level='inicio';if(key==='style')answers.piece='americano';app.querySelectorAll('[data-value]').forEach(el=>{el.disabled=true;const picked=el===b;el.classList.toggle('selected',picked);el.setAttribute('aria-pressed',picked);el.querySelector('.circle').textContent=picked?'✓':''});nextTimer=setTimeout(()=>go(current+1),240);}});if(isMulti)document.querySelector('#multi-continue').onclick=()=>go(current+1);}
function nameStep(){app.innerHTML=`<section class="step name-step"><span class="label">CASA DO ARTESANATO</span><h1>Qual é o seu<br><em>nome?</em></h1><form id="name-form"><input id="first-name" name="name" type="text" autocomplete="given-name" maxlength="40" placeholder="Digite seu nome" value="${escapeHtml(answers.name||'')}" required><p class="name-error" id="name-error" role="alert"></p>${cta('CONTINUAR')}</form></section>`;document.querySelector('#name-form').onsubmit=e=>{e.preventDefault();const input=document.querySelector('#first-name');const value=input.value.trim().replace(/\\s+/g,' ');if(value.length<2){document.querySelector('#name-error').textContent='Digite pelo menos 2 letras.';input.focus();return;}answers.name=value;go(current+1);};}
function loading(){app.innerHTML=`<section class="step loading-step"><div class="loading-orbit" aria-hidden="true"><span class="orbit-ring"></span><span class="orbit-icon">✂️</span><i class="orbit-spark one">✦</i><i class="orbit-spark two">✧</i></div><h1>${person()}, estamos<br><em>montando sua seleção.</em></h1><p>Analisando suas respostas e preparando uma prévia dos seus moldes.</p><div class="loading-percent" id="load-percent">0%</div><div class="loading-bar animated-loading-bar" role="progressbar" aria-label="Analisando informações" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span id="load-fill"><i></i></span></div><div class="loading-checks"><div id="load-1">○ Conferindo suas escolhas</div><div id="load-2">○ Organizando seus estilos</div><div id="load-3">○ Preparando sua prévia</div></div></section>`;const start=performance.now();loadingTimer=setInterval(()=>{const value=Math.min(100,Math.floor((performance.now()-start)/50));document.querySelector('#load-percent').textContent=value+'%';document.querySelector('#load-fill').style.width=value+'%';document.querySelector('.loading-bar').setAttribute('aria-valuenow',value);for(let i=1;i<=3;i++){const el=document.querySelector('#load-'+i);if(value>=[20,55,90][i-1]){el.classList.add('done');el.textContent=el.textContent.replace('○','✓');}}if(value===100){clearInterval(loadingTimer);nextTimer=setTimeout(()=>go(current+1),220);}},50);}
function preview(){const images=['preview-1.png','preview-2.png','preview-3.png'];app.innerHTML=`<section class="step preview-step"><div class="preview-top"><h1>Parabéns, ${person()}!<br><em>Sua seleção está pronta.</em></h1></div><div class="preview-gallery">${images.map((img,i)=>`<figure><img src="assets/${img}" alt="Prévia de molde de mesa posta ${i+1}"><figcaption>${['Capa dos 300 moldes em PDF','Mandala Corações','Molde em tamanho real'][i]}</figcaption></figure>`).join('')}</div>${cta('VER MAIS MOLDES')}</section>`;bindContinue();}
function offer(){const name=person();app.innerHTML=`<section class="step lp"><div class="lp-shell"><div class="lp-hero lp-card"><span class="eyebrow">COLEÇÃO MESA POSTA</span><h1>300 moldes em PDF<br><em>para suas mesas</em></h1><p>Modelos prontos para imprimir, recortar e transformar em peças que encantam.</p><img src="assets/cover-300-moldes.png" class="lp-cover" alt="Capa dos 300 moldes de mesa posta"></div><section class="lp-section lp-card"><h2>Inspirações de peças prontas</h2><p class="section-lead">Veja algumas ideias de peças que você pode criar com os moldes.</p><div class="moldes-grid real-results"><figure><img src="assets/previa-mesa-1.png" alt="Mesa posta natalina com velas"><figcaption>Mesa posta de Natal</figcaption></figure><figure><img src="assets/previa-mesa-2.png" alt="Mesa posta com flores e sousplats"><figcaption>Sousplat floral</figcaption></figure><figure><img src="assets/previa-mesa-3.png" alt="Mesa posta elegante com velas"><figcaption>Mesa rústica elegante</figcaption></figure></div></section><section class="lp-section lp-card complete"><h2>O que você recebe no material completo</h2><div class="benefit-grid"><article><b>🎄 Moldes natalinos</b><p>Modelos para Natal e fim de ano.</p></article><article><b>🍽️ Mesa posta</b><p>Jogos americanos, sousplats e composições.</p></article><article><b>🧶 Trilhos de mesa</b><p>Peças para deixar a mesa completa.</p></article><article><b>🌿 Mesa rústica</b><p>Acabamentos naturais e elegantes.</p></article><article><b>✨ Mesa americana</b><p>Modelos versáteis para vender ou presentear.</p></article><article><b>📐 Arquivos em tamanho real</b><p>PDFs organizados, prontos para imprimir.</p></article></div></section><section class="lp-section lp-card bonus-block"><h2>E ainda recebe estes bônus</h2><div class="bonus-row video-bonus"><div class="video-bonus-art"><span>▶</span><small>AULA 01</small></div><div><h3>Videoaulas práticas</h3><p>Aprenda a escolher, imprimir e montar cada peça com orientação passo a passo.</p></div></div><div class="bonus-row"><span class="bonus-icon">📋</span><div><h3>Lista de materiais</h3><p>Saiba exatamente o que separar antes de começar.</p></div></div></section><section class="lp-offer lp-card"><span class="offer-tag">ACESSO COMPLETO</span><h2>Libere seus 300 moldes</h2><p>Receba o material completo por apenas:</p><strong>R$ 10,00</strong><small>Pagamento único · acesso digital</small>${cta('LIBERAR 300 MOLDES POR R$ 10,00','checkout')}<img class="lp-seals" src="assets/selos-garantia.png" alt="Compra segura, satisfação garantida e privacidade protegida"></section><section class="lp-section lp-card lp-reviews"><h2>Experiências com o material</h2><div class="video-review"><img src="assets/review-3.png" alt="Depoimento de cliente"><span class="video-play">▶</span></div><div class="review-cards human-reviews"><article><img src="assets/review-1.png" alt="Ana Paula"><div><b>Ana Paula — Campinas, SP</b><span>★★★★★</span><p>“Eu estava perdida com tantos modelos. Imprimi o primeiro no mesmo dia e minha mesa ficou outra coisa.”</p></div></article><article><img src="assets/review-2.png" alt="Jéssica"><div><b>Jéssica — Curitiba, PR</b><span>★★★★★</span><p>“Amei ter as medidas certinhas. Já fiz três peças e minhas amigas começaram a pedir encomenda.”</p></div></article><article><img src="assets/review-3.png" alt="Renata"><div><b>Renata — Salvador, BA</b><span>★★★★★</span><p>“Os moldes são bonitos e muito fáceis de entender. O material superou o que eu esperava.”</p></div></article></div></section><section class="lp-section lp-card faq-section"><h2>Dúvidas frequentes</h2><p class="faq-intro">Tudo explicado de forma simples para você comprar com segurança.</p><details><summary>O que exatamente eu recebo?</summary><p>Você recebe uma coleção digital com 300 moldes em PDF, organizados por temas e prontos para baixar e imprimir. Também estão incluídos o guia de produção, a lista de materiais e as videoaulas bônus.</p></details><details><summary>Os moldes vêm em tamanho real?</summary><p>Sim. Os arquivos foram preparados para você imprimir em folhas comuns e montar as partes seguindo as indicações do próprio material.</p></details><details><summary>Posso usar os moldes para fazer peças para vender?</summary><p>Sim. Você pode usar os moldes para produzir jogos americanos, sousplats, trilhos e outras peças para sua casa, presentes ou encomendas.</p></details><details><summary>Preciso ter experiência para começar?</summary><p>Não. O guia mostra o caminho desde a escolha do modelo até a montagem. As videoaulas ajudam quem está começando e também quem quer ganhar agilidade.</p></details><details><summary>Como recebo o acesso ao material?</summary><p>Depois da confirmação do pagamento, o acesso é enviado digitalmente. Você pode salvar os arquivos no celular ou computador e imprimir quando quiser.</p></details><details><summary>Tenho garantia para conhecer o conteúdo?</summary><p>Sim. Você tem 7 dias para abrir os arquivos, assistir às aulas e conferir se o material atende ao que foi apresentado.</p></details><details><summary>O pagamento é seguro?</summary><p>Sim. A finalização acontece em ambiente protegido, com os dados tratados de forma segura pela plataforma de pagamento.</p></details></section></section></div></section><dialog id="discount-modal" class="discount-native"><div class="discount-popup"><button class="modal-x" id="modal-close" aria-label="Fechar">×</button><div class="discount-gift">🎁</div><span class="discount-kicker">CONDIÇÃO ESPECIAL</span><h2>${name}, libere seu acesso completo</h2><p>De <s>R$ 99,00</s> por apenas:</p><strong class="modal-price">R$ 10,00</strong><small class="modal-copy">Acesso aos 300 moldes em PDF + bônus.</small>${cta('LIBERAR MEUS 300 MOLDES','modal-checkout')}</div></dialog>`;document.querySelector('#checkout').onclick=()=>{if(config.checkoutUrl)window.location.assign(config.checkoutUrl)};document.querySelector('#modal-checkout').onclick=()=>{if(config.checkoutUrl)window.location.assign(config.checkoutUrl);else document.querySelector('#discount-modal').close()};document.querySelector('#modal-close').onclick=()=>document.querySelector('#discount-modal').close();setTimeout(()=>document.querySelector('#discount-modal').showModal(),180);}
function bindContinue(){document.querySelector('#continue').onclick=()=>go(current+1)}
document.querySelector('#back').onclick=()=>go(current-1);render();

// A oferta é aberta dentro da própria landing page; a navegação só acontece
// quando a pessoa confirma o acesso no botão do popup.
document.addEventListener('click',event=>{const button=event.target.closest('#checkout');if(!button)return;event.preventDefault();event.stopImmediatePropagation();document.querySelector('#discount-modal')?.showModal()},true);
document.addEventListener('click',event=>{const button=event.target.closest('#modal-checkout');if(!button)return;event.preventDefault();event.stopImmediatePropagation();document.querySelector('#discount-modal')?.close()},true);
setTimeout(()=>document.querySelector('#discount-modal')?.close(),220);
const offerPopupStyle=document.createElement('style');offerPopupStyle.textContent='.discount-native .modal-x{display:none!important}';document.head.append(offerPopupStyle);
